// Minimal stand-in for `next/server`, used only to execute the real
// `frontend/src/app/api/[...slug]/route.ts` handler outside of Next.js.
//
// The route handler only ever relies on:
//   - NextResponse.json(body, init)
//   - the type-only imports NextRequest / NextResponse
// so a tiny shim is enough to run the exact production code path.

export class NextResponse {
  constructor(body, init = {}) {
    this.status = init.status ?? 200;
    this.headers = init.headers ?? {};
    this._body = body;
  }

  static json(body, init) {
    return new NextResponse(body, init);
  }

  async json() {
    return this._body;
  }

  async text() {
    return typeof this._body === "string"
      ? this._body
      : JSON.stringify(this._body);
  }
}

export class NextRequest {}
